-- Generated by scripts/store-baseline-gen; do not edit by hand.
-- Regenerate with: go generate ./internal/store
--
-- A consolidated head-schema snapshot for brand-new databases. Existing
-- databases keep the shipped migration chain as their only upgrade path.

CREATE TABLE annotation_classes (
    id           TEXT PRIMARY KEY,
    class        TEXT NOT NULL UNIQUE,
    display_name TEXT NOT NULL,
    description  TEXT
) STRICT;

CREATE TABLE annotation_families (
    id           TEXT PRIMARY KEY,
    family       TEXT NOT NULL UNIQUE,
    class_id     TEXT NOT NULL REFERENCES annotation_classes(id),
    display_name TEXT NOT NULL,
    description  TEXT
) STRICT;

CREATE TABLE annotation_run_state (
    session_id TEXT PRIMARY KEY,
    session_entries_hash TEXT NOT NULL CHECK (
        length(session_entries_hash) = 64 AND session_entries_hash NOT GLOB '*[^0-9a-f]*'
    ),
    compute_version INTEGER NOT NULL,
    classifier_version INTEGER NOT NULL,
    annotated_at INTEGER NOT NULL, metrics_output_hash TEXT CHECK (
    metrics_output_hash IS NULL OR (length(metrics_output_hash) = 64 AND metrics_output_hash NOT GLOB '*[^0-9a-f]*')
),
    FOREIGN KEY(session_id) REFERENCES sessions(session_id) ON DELETE CASCADE
);

CREATE TABLE annotation_statuses (
    id   INTEGER PRIMARY KEY,
    name TEXT NOT NULL UNIQUE
) STRICT;

CREATE TABLE annotation_target_anchors (
    annotation_id TEXT PRIMARY KEY REFERENCES annotations(id) ON DELETE CASCADE,
    session_id TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE,
    entry_index INTEGER,
    end_index INTEGER,
    state TEXT NOT NULL CHECK (state IN ('resolved', 'unresolved', 'superseded')),
    entry_id TEXT,
    tool_call_id TEXT,
    entry_type TEXT,
    role TEXT,
    part_type TEXT,
    content_fingerprint TEXT,
    updated_at INTEGER NOT NULL,
    CHECK ((state = 'resolved' AND entry_index IS NOT NULL AND end_index IS NOT NULL AND end_index > entry_index) OR state IN ('unresolved', 'superseded'))
) STRICT;

CREATE TABLE annotation_target_annotations (
    annotation_id        TEXT PRIMARY KEY REFERENCES annotations(id) ON DELETE CASCADE,
    target_annotation_id TEXT NOT NULL REFERENCES annotations(id)
) STRICT;

CREATE TABLE annotation_target_associations (
    annotation_id  TEXT PRIMARY KEY REFERENCES annotations(id) ON DELETE CASCADE,
    association_id TEXT NOT NULL REFERENCES session_commit_associations(association_id)
) STRICT;

CREATE TABLE "annotation_target_entries" (
    annotation_id TEXT PRIMARY KEY REFERENCES annotations(id) ON DELETE CASCADE,
    session_id    TEXT NOT NULL,
    entry_index   INTEGER NOT NULL,
    end_index     INTEGER NOT NULL,
    CHECK (end_index > entry_index)
) STRICT;

CREATE TABLE annotation_target_projects (
    annotation_id TEXT PRIMARY KEY REFERENCES annotations(id) ON DELETE CASCADE,
    project_hash  TEXT NOT NULL REFERENCES projects(project_hash)
) STRICT;

CREATE TABLE annotation_target_sessions (
    annotation_id TEXT PRIMARY KEY REFERENCES annotations(id) ON DELETE CASCADE,
    session_id    TEXT NOT NULL REFERENCES sessions(session_id)
) STRICT;

CREATE TABLE annotation_type_deps (
    annotation_type_id TEXT NOT NULL REFERENCES annotation_types(id),
    depends_on_id      TEXT NOT NULL REFERENCES annotation_types(id),
    required           INTEGER NOT NULL DEFAULT 1 CHECK (required IN (0, 1)),
    rationale          TEXT,
    PRIMARY KEY (annotation_type_id, depends_on_id),
    CHECK (annotation_type_id != depends_on_id)
) STRICT;

CREATE TABLE annotation_type_target_kinds (
    annotation_type_id TEXT NOT NULL REFERENCES annotation_types(id) ON DELETE CASCADE,
    target_kind_id     INTEGER NOT NULL REFERENCES target_kinds(id),
    PRIMARY KEY (annotation_type_id, target_kind_id)
) STRICT;

CREATE TABLE annotation_types (
    id                 TEXT PRIMARY KEY,
    type_id            TEXT NOT NULL UNIQUE,
    version            INTEGER NOT NULL DEFAULT 1,
    display_name       TEXT NOT NULL,
    description        TEXT,
    family_id          TEXT NOT NULL REFERENCES annotation_families(id),
    value_domain_kind_id INTEGER NOT NULL REFERENCES value_domain_kinds(id),
    datatype           TEXT NOT NULL
                       CHECK (datatype IN ('text', 'integer', 'real', 'boolean')),
    value_constraint   TEXT NOT NULL,
    lower_is_better    INTEGER CHECK (lower_is_better IN (0, 1)),
    status_id          INTEGER NOT NULL DEFAULT 1 REFERENCES annotation_statuses(id),
    origin_id          INTEGER NOT NULL REFERENCES type_origins(id),
    priority_override  INTEGER,
    created_at         INTEGER NOT NULL,
    updated_at         INTEGER,
    deprecated_at      INTEGER,
    superseded_by      TEXT REFERENCES annotation_types(id), scale_kind_id INTEGER REFERENCES scale_kinds(id),
    CHECK (type_id LIKE '%.%')
) STRICT;

CREATE TABLE annotations (
    id                 TEXT PRIMARY KEY,
    target_kind_id     INTEGER NOT NULL REFERENCES target_kinds(id),
    annotation_type_id TEXT NOT NULL REFERENCES annotation_types(id),
    annotator_id       TEXT NOT NULL REFERENCES annotators(id),
    value              TEXT NOT NULL,
    confidence         REAL,
    reason             TEXT,
    provenance         TEXT,
    is_primary         INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0, 1)),
    content_hash       TEXT,
    created_at         INTEGER NOT NULL,
    updated_at         INTEGER,
    superseded_by      TEXT REFERENCES annotations(id)
, retired_at INTEGER) STRICT;

CREATE TABLE annotator_kinds (
    id   INTEGER PRIMARY KEY,
    name TEXT NOT NULL UNIQUE
) STRICT;

CREATE TABLE annotators (
    id            TEXT PRIMARY KEY,
    kind_id       INTEGER NOT NULL REFERENCES annotator_kinds(id),
    name          TEXT NOT NULL UNIQUE,
    display_name  TEXT NOT NULL,
    description   TEXT,
    model_id      TEXT,
    provider_key  TEXT,
    status        TEXT NOT NULL DEFAULT 'active'
                  CHECK (status IN ('active', 'inactive')),
    created_at    INTEGER NOT NULL,
    FOREIGN KEY (model_id, provider_key) REFERENCES models(model_id, provider_key),
    CHECK (kind_id != 2 OR (model_id IS NOT NULL AND provider_key IS NOT NULL)),
    CHECK (kind_id = 2 OR (model_id IS NULL AND provider_key IS NULL))
) STRICT;

CREATE TABLE claude_transcript_evidence (
  source_path TEXT PRIMARY KEY,
  scope TEXT NOT NULL CHECK(scope IN ('root', 'subagent')),
  mod_time_unix_nano INTEGER NOT NULL,
  size_bytes INTEGER NOT NULL CHECK(size_bytes >= 0),
  has_conversation INTEGER NOT NULL CHECK(has_conversation IN (0, 1)),
  identity_team TEXT,
  identity_name TEXT,
  spawns_json TEXT NOT NULL CHECK(json_valid(spawns_json)),
  title TEXT NOT NULL,
  branch TEXT NOT NULL,
  cwd TEXT NOT NULL, origin TEXT NOT NULL DEFAULT ''
  CHECK (origin IN ('', 'user', 'agent', 'unknown')),
  CHECK((identity_team IS NULL) = (identity_name IS NULL))
) STRICT;

CREATE TABLE daily_summary (
    date_utc        TEXT PRIMARY KEY,
    session_count   INTEGER NOT NULL DEFAULT 0,
    tokens_in       INTEGER NOT NULL DEFAULT 0,
    tokens_out      INTEGER NOT NULL DEFAULT 0,
    tokens_total    INTEGER NOT NULL DEFAULT 0,
    avg_duration_ms REAL    NOT NULL DEFAULT 0,
    avg_turns       REAL    NOT NULL DEFAULT 0,
    tool_call_count INTEGER NOT NULL DEFAULT 0
, total_cost_usd REAL, avg_cost_per_session_usd REAL, acceptance_rate REAL) STRICT;

CREATE TABLE daily_summary_by_project (
    date_utc       TEXT NOT NULL,
    project_hash   TEXT NOT NULL,
    project_path   TEXT,
    session_count  INTEGER NOT NULL DEFAULT 0,
    total_tokens   INTEGER NOT NULL DEFAULT 0,
    total_tool_calls INTEGER NOT NULL DEFAULT 0,
    total_duration_minutes REAL NOT NULL DEFAULT 0,
    resolved_count INTEGER NOT NULL DEFAULT 0,
    failed_count   INTEGER NOT NULL DEFAULT 0,
    partial_count  INTEGER NOT NULL DEFAULT 0,
    avg_spec_quality REAL,
    acceptance_rate REAL,
    total_cost_usd REAL,
    PRIMARY KEY (date_utc, project_hash)
) STRICT;

CREATE TABLE daily_summary_harness (
    date_utc TEXT NOT NULL,
    model_harness TEXT NOT NULL CHECK (model_harness IN ('claude-code','opencode','codex','gemini-cli','cursor','antigravity','strike','pi')),
    session_count INTEGER NOT NULL DEFAULT 0,
    tokens_in INTEGER NOT NULL DEFAULT 0,
    tokens_out INTEGER NOT NULL DEFAULT 0,
    tokens_total INTEGER NOT NULL DEFAULT 0,
    avg_duration_ms REAL NOT NULL DEFAULT 0,
    avg_turns REAL NOT NULL DEFAULT 0,
    tool_call_count INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (date_utc, model_harness)
) STRICT, WITHOUT ROWID;

CREATE TABLE file_familiarity (
    project_hash       TEXT NOT NULL REFERENCES projects(project_hash),
    file_path          TEXT NOT NULL,
    familiarity_depth  INTEGER NOT NULL DEFAULT 0,
    session_count      INTEGER NOT NULL DEFAULT 0,
    total_turns        INTEGER NOT NULL DEFAULT 0,
    total_human_turns  INTEGER NOT NULL DEFAULT 0,
    first_engaged_at   TEXT,
    last_engaged_at    TEXT,
    PRIMARY KEY (project_hash, file_path)
) STRICT;

CREATE TABLE host_slugs (
    opaque_id        TEXT PRIMARY KEY,
    host_slug        TEXT NOT NULL,
    git_remote       TEXT,
    canonical_remote TEXT
) STRICT;

CREATE TABLE index_log (
    id                INTEGER PRIMARY KEY AUTOINCREMENT,
    session_id        TEXT NOT NULL,
    provider          TEXT NOT NULL,
    outcome           TEXT NOT NULL CHECK (outcome IN ('indexed','reindexed','fallback','skipped','error')),
    index_version     INTEGER NOT NULL,
    entries_count     INTEGER NOT NULL DEFAULT 0,
    source_path       TEXT,
    original_root     TEXT,
    reason            TEXT,
    started_at        INTEGER NOT NULL,
    finished_at       INTEGER,
    error_message     TEXT
, index_format_version INTEGER CHECK (index_format_version > 0)) STRICT;

CREATE TABLE ingest_log (
    id                INTEGER PRIMARY KEY AUTOINCREMENT,
    started_at        INTEGER NOT NULL,
    finished_at       INTEGER,
