    content_hash      TEXT NOT NULL,
    visibility        TEXT NOT NULL,
    pull_dir          TEXT NOT NULL,
    first_pulled_at   INTEGER NOT NULL,
    last_pulled_at    INTEGER NOT NULL,
    annotation_count  INTEGER NOT NULL DEFAULT 0, license_id TEXT CHECK (license_id IN ('CC0-1.0', 'CC-BY-4.0', 'CC-BY-SA-4.0')),
    PRIMARY KEY (village_host, transcript_id)
) STRICT;

CREATE TABLE push_log (
