    PRIMARY KEY (session_id, entry_index),
    FOREIGN KEY (session_id, entry_index) REFERENCES session_entries(session_id, entry_index) ON DELETE CASCADE
) STRICT;

CREATE TABLE session_commit_associations (
    association_id       TEXT PRIMARY KEY,
    session_id           TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE,
    observed_commit_hash TEXT NOT NULL,
    subject              TEXT,
    author_time          INTEGER,
    created_at           INTEGER NOT NULL DEFAULT (unixepoch('now') * 1000),
    UNIQUE (session_id, observed_commit_hash)
) STRICT;

CREATE TABLE session_commits (
    session_id   TEXT NOT NULL REFERENCES sessions(session_id),
    commit_hash  TEXT NOT NULL,
    author_name  TEXT,
    author_email TEXT,
    message      TEXT,
    commit_time  INTEGER,
    author_time  INTEGER,
    created_at   INTEGER NOT NULL DEFAULT (unixepoch('now') * 1000),
    PRIMARY KEY (session_id, commit_hash)
) STRICT;

CREATE TABLE session_content (
  session_id  TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE,
  digest      TEXT NOT NULL CHECK(length(digest) = 64),
  byte_length INTEGER NOT NULL CHECK(byte_length >= 0),
  chunk_count INTEGER GENERATED ALWAYS AS ((byte_length + 65535) / 65536) VIRTUAL,
  PRIMARY KEY (session_id, digest)
) STRICT, WITHOUT ROWID;

CREATE TABLE session_content_captures (
 session_id TEXT PRIMARY KEY REFERENCES sessions(session_id) ON DELETE CASCADE,
 status TEXT NOT NULL CHECK(status IN ('complete','incomplete','failed')),
 source_authority TEXT NOT NULL CHECK(source_authority IN ('new_ingest','peasant_snapshot','provider_source','none')),
 transcript_origin INTEGER NOT NULL DEFAULT 0,
 capture_format TEXT NOT NULL CHECK(capture_format IN ('full','preview_only','legacy_preview_only')),
 entry_count INTEGER NOT NULL CHECK(entry_count >= 0),
 content_row_count INTEGER NOT NULL CHECK(content_row_count >= 0),
 full_capture_sha256 TEXT CHECK(full_capture_sha256 IS NULL OR length(full_capture_sha256)=64),
 captured_at_ms INTEGER NOT NULL,
 failure_code TEXT,
 failure_message TEXT,
	publication_capture_revision INTEGER NOT NULL DEFAULT 0 CHECK(publication_capture_revision >= 0),
 CHECK(status != 'complete' OR (full_capture_sha256 IS NOT NULL AND failure_code IS NULL AND failure_message IS NULL))
) STRICT;

CREATE TABLE session_content_chunks (
  session_id  TEXT NOT NULL,
  digest      TEXT NOT NULL,
  chunk_index INTEGER NOT NULL CHECK(chunk_index >= 0),
  data        BLOB NOT NULL CHECK(length(data) BETWEEN 1 AND 65536),
  UNIQUE (session_id, digest, chunk_index),
  FOREIGN KEY (session_id, digest) REFERENCES session_content(session_id, digest) ON DELETE CASCADE
) STRICT;

CREATE TABLE session_context_segment_refs (
  session_id TEXT NOT NULL,
  generation_id TEXT NOT NULL,
  segment_ordinal INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  source_entry_ref TEXT NOT NULL,
  PRIMARY KEY (session_id, generation_id, segment_ordinal, ordinal),
  FOREIGN KEY (session_id, generation_id, segment_ordinal)
    REFERENCES session_context_segments(session_id, generation_id, segment_ordinal) ON DELETE CASCADE
) STRICT;

CREATE TABLE "session_context_segments" (
  session_id                TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE,
  generation_id             TEXT NOT NULL,
  segment_ordinal           INTEGER NOT NULL CHECK(segment_ordinal >= 0),
  logical_session_id        TEXT,
  physical_source_id        TEXT NOT NULL,
  coordinate_kind           TEXT NOT NULL,
  start_coordinate          INTEGER,
  end_exclusive             INTEGER,
  decoded_byte_start        INTEGER,
  decoded_byte_end_exclusive INTEGER,
  inclusion                 TEXT NOT NULL,
  PRIMARY KEY (session_id, generation_id, segment_ordinal)
) STRICT;

CREATE TABLE session_entries (
    session_id      TEXT NOT NULL REFERENCES sessions(session_id),
    entry_index     INTEGER NOT NULL,
    provider        TEXT NOT NULL,
    entry_type      TEXT NOT NULL CHECK (entry_type IN ('text','tool_use','tool_result','thinking','system','error','result')),
    role            TEXT NOT NULL CHECK (role IN ('user','assistant','tool','system')),
    timestamp_ms    INTEGER,
    content_preview TEXT,
    tokens_in       INTEGER,
    tokens_out      INTEGER,
    has_tool_use    INTEGER NOT NULL DEFAULT 0 CHECK (has_tool_use IN (0,1)),
    tool_names_csv  TEXT,
    has_thinking    INTEGER NOT NULL DEFAULT 0 CHECK (has_thinking IN (0,1)),
    is_error        INTEGER NOT NULL DEFAULT 0 CHECK (is_error IN (0,1)),
    raw_byte_length INTEGER,
    tool_call_id     TEXT,
    entry_id        TEXT,
    parent_entry_id TEXT,
    extra           TEXT, depth INTEGER NOT NULL DEFAULT 0, parent_index INTEGER, tool_input TEXT, tool_output TEXT, tool_kind TEXT, stop_reason TEXT, part_type TEXT,
    PRIMARY KEY (session_id, entry_index)
) STRICT;

CREATE TABLE session_entries_ext (
    session_id   TEXT NOT NULL,
    entry_index  INTEGER NOT NULL,
    key          TEXT NOT NULL,
    value_text   TEXT,
    value_int    INTEGER,
    value_real   REAL,
    PRIMARY KEY (session_id, entry_index, key),
    FOREIGN KEY (session_id, entry_index)
      REFERENCES session_entries(session_id, entry_index) ON DELETE CASCADE
) STRICT;

CREATE VIRTUAL TABLE session_entries_fts USING fts5(
    content_preview,
    tool_input,
    tool_output,
    session_id UNINDEXED,
    entry_index UNINDEXED,
    content='session_entries',
    content_rowid='rowid',
    tokenize='unicode61 remove_diacritics 2'
);

CREATE TABLE session_entry_bodies (
  body_id          INTEGER PRIMARY KEY CHECK(body_id >= 1125899906842624),
  session_id       TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE,
  body_digest      TEXT NOT NULL CHECK(length(body_digest) = 64),
  entry_index      INTEGER NOT NULL CHECK(entry_index >= 0),
  harness          TEXT NOT NULL,
  entry_type       TEXT NOT NULL,
  role             TEXT NOT NULL,
  timestamp_ms     INTEGER,
  content_preview  TEXT,
  tokens_in        INTEGER,
  tokens_out       INTEGER,
  has_tool_use     INTEGER NOT NULL CHECK(has_tool_use IN (0,1)),
  tool_kind        TEXT,
  tool_names_csv   TEXT,
  has_thinking     INTEGER NOT NULL CHECK(has_thinking IN (0,1)),
  is_error         INTEGER NOT NULL CHECK(is_error IN (0,1)),
  stop_reason      TEXT,
  raw_byte_length  INTEGER,
  tool_call_id     TEXT,
  entry_id         TEXT,
  parent_entry_id  TEXT,
  depth            INTEGER NOT NULL,
  parent_index     INTEGER,
  tool_input       TEXT,
  tool_output      TEXT,
  model_id         TEXT,
  tokens_reasoning INTEGER,
  cache_read       INTEGER,
  cache_write      INTEGER,
  extra            TEXT,
  extra_verbatim   TEXT,
  part_type        TEXT,
  source_entry_ref TEXT,
  prov_origin      TEXT,
  prov_actor       TEXT,
  prov_delivery    TEXT,
  prov_ownership   TEXT,
  prov_evidence    TEXT,
  prov_input_modality TEXT,
  prov_submission_ref TEXT,
  UNIQUE (session_id, body_digest),
  CHECK (extra IS NULL OR extra_verbatim IS NULL)
) STRICT;

CREATE TABLE session_entry_full_content (
 session_id TEXT NOT NULL,
 entry_index INTEGER NOT NULL,
 full_byte_length INTEGER NOT NULL CHECK(full_byte_length >= 0),
 full_sha256 TEXT NOT NULL CHECK(length(full_sha256)=64),
 preview_byte_length INTEGER NOT NULL CHECK(preview_byte_length >= 0),
 preview_sha256 TEXT NOT NULL CHECK(length(preview_sha256)=64),
 preview_is_full INTEGER NOT NULL CHECK(preview_is_full IN (0,1)),
 chunk_count INTEGER NOT NULL CHECK(chunk_count >= 0),
 captured_at_ms INTEGER NOT NULL,
 PRIMARY KEY(session_id,entry_index),
 FOREIGN KEY(session_id,entry_index) REFERENCES session_entries(session_id,entry_index) ON DELETE CASCADE
