CREATE TABLE session_entry_full_content_chunks (
 session_id TEXT NOT NULL,
 entry_index INTEGER NOT NULL,
 chunk_index INTEGER NOT NULL,
 byte_offset INTEGER NOT NULL CHECK(byte_offset >= 0),
