CREATE TABLE session_generation_diagnostics (
  session_id TEXT NOT NULL,
  generation_id TEXT NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  error_type TEXT NOT NULL,
  location TEXT NOT NULL,
  message TEXT NOT NULL,
  remediation TEXT NOT NULL,
  PRIMARY KEY (session_id, generation_id, ordinal),
  FOREIGN KEY (session_id, generation_id) REFERENCES session_generations(session_id, generation_id) ON DELETE CASCADE
) STRICT;

CREATE TABLE session_generation_entries (
  session_id       TEXT NOT NULL,
  generation_id    TEXT NOT NULL,
  partition_id     INTEGER NOT NULL CHECK(partition_id >= 0),
  entry_index      INTEGER NOT NULL CHECK(entry_index >= 0),
  source_entry_ref TEXT,
  body_digest      TEXT NOT NULL,
  PRIMARY KEY (session_id, generation_id, partition_id, entry_index),
  FOREIGN KEY (session_id, generation_id) REFERENCES session_generations(session_id, generation_id) ON DELETE CASCADE,
  FOREIGN KEY (session_id, body_digest)   REFERENCES session_entry_bodies(session_id, body_digest)
) STRICT;

CREATE TABLE session_generation_subagents (
  session_id TEXT NOT NULL,
  generation_id TEXT NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  subagent_session_id TEXT NOT NULL,
  parent_uuid TEXT NOT NULL,
  PRIMARY KEY (session_id, generation_id, ordinal),
  FOREIGN KEY (session_id, generation_id) REFERENCES session_generations(session_id, generation_id) ON DELETE CASCADE
) STRICT;

CREATE TABLE session_generation_title_refs (
  session_id TEXT NOT NULL,
  generation_id TEXT NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  source_entry_ref TEXT NOT NULL,
  PRIMARY KEY (session_id, generation_id, ordinal),
  FOREIGN KEY (session_id, generation_id) REFERENCES session_generations(session_id, generation_id) ON DELETE CASCADE
) STRICT;

CREATE TABLE session_generations (
  session_id             TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE,
  generation_id          TEXT NOT NULL,
  schema_version         INTEGER NOT NULL,
  harness                TEXT NOT NULL,
  model                  TEXT NOT NULL,
  version                TEXT NOT NULL,
  ts_start               INTEGER NOT NULL,
  ts_end                 INTEGER NOT NULL,
  ts_ingested            INTEGER,
  source_file_path       TEXT,
  source_format          TEXT NOT NULL,
  git_branch             TEXT,
  git_remote             TEXT,
  git_worktree           TEXT,
  git_tracking           TEXT,
  project_hash           TEXT NOT NULL,
  project_file_path      TEXT,
  project_name           TEXT NOT NULL,
  host_slug              TEXT NOT NULL,
  root_session_id        TEXT,
  purpose                TEXT,
  cwd                    TEXT,
  derived_at             INTEGER,
  content_hash           TEXT NOT NULL,
  metadata_hash          TEXT NOT NULL CHECK(length(metadata_hash) = 64),
  redaction_applied      INTEGER NOT NULL CHECK(redaction_applied IN (0,1)),
  redaction_level        TEXT,
  redaction_rule_set_version TEXT,
  redaction_at_ms        INTEGER,
  redaction_content_hash_at_redact TEXT,
  adapter_version        INTEGER,
  diagnostics_partial    INTEGER CHECK(diagnostics_partial IS NULL OR diagnostics_partial IN (0,1)),
  completeness           TEXT NOT NULL CHECK(completeness IN ('complete','incomplete_new')),
  source_evidence_digest TEXT NOT NULL CHECK(length(source_evidence_digest) = 64),
  index_format_version   INTEGER NOT NULL CHECK(index_format_version = 2),
  candidate_digest       TEXT NOT NULL CHECK(length(candidate_digest) = 64),
  prior_evidence         BLOB,
  installed_at_ms        INTEGER NOT NULL CHECK(installed_at_ms >= 0),
  activated_at_ms        INTEGER CHECK(activated_at_ms IS NULL OR activated_at_ms >= 0),
  PRIMARY KEY (session_id, generation_id)
) STRICT;

CREATE TABLE session_metrics (
    session_id       TEXT PRIMARY KEY REFERENCES sessions(session_id),
    -- Retained v1 columns (no v2 equivalent; independently useful)
    turn_count       INTEGER,
    subagent_count   INTEGER,
    -- v2 QualitySession columns
    title            TEXT,
    outcome          TEXT CHECK(outcome IN ('resolved','partial','failed')),
    total_tokens     INTEGER,
    input_tokens     INTEGER,
    output_tokens    INTEGER,
    tool_calls       INTEGER,
    files_touched    INTEGER,
    lines_changed    INTEGER,
    duration_minutes REAL,
    retry_loops      INTEGER,
    retry_tokens_wasted INTEGER,
    within_session_reverts INTEGER,
    signal_density   REAL,
    spec_quality_score REAL,
    exploration_ratio REAL,
    scope_breadth    INTEGER,
    discovery_turns  INTEGER,
    -- M-series (v2 — stubbed)
    m2_token_outcome_ratio    REAL,
    m3_unique_tool_count      INTEGER,
    m4_error_recovery_count   INTEGER,
    m4_consecutive_error_max  INTEGER,
    m5_context_utilization_pct REAL,
    m5_peak_context_tokens    INTEGER,
    m5_avg_message_tokens     INTEGER,
    m6_output_survival_pct    REAL,
    m6_lines_survived         INTEGER,
    m6_lines_total            INTEGER,
    m7_spec_word_count        INTEGER,
    m7_spec_has_examples      INTEGER NOT NULL DEFAULT 0,
    m7_spec_has_constraints   INTEGER NOT NULL DEFAULT 0,
    -- Metadata
    computed_at      INTEGER,
    compute_version  INTEGER NOT NULL DEFAULT 0
, cost_input_usd REAL, cost_output_usd REAL, cost_reasoning_usd REAL, cost_cache_read_usd REAL, cost_cache_write_usd REAL, cost_total_usd REAL, cost_model_id TEXT, scope TEXT, input_hash TEXT CHECK (
    input_hash IS NULL OR (length(input_hash) = 64 AND input_hash NOT GLOB '*[^0-9a-f]*')
), output_hash TEXT CHECK (
    output_hash IS NULL OR (length(output_hash) = 64 AND output_hash NOT GLOB '*[^0-9a-f]*')
)) STRICT;

CREATE TABLE session_migration_gaps (
  id INTEGER PRIMARY KEY,
  session_id TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE,
  generation_id TEXT NOT NULL,
  source_table TEXT NOT NULL,
  source_column TEXT NOT NULL,
  source_ordinal INTEGER NOT NULL CHECK(source_ordinal >= 0),
  observed_json_type TEXT NOT NULL,
  observed_length INTEGER NOT NULL CHECK(observed_length >= 0),
  message TEXT NOT NULL,
  remediation TEXT NOT NULL,
  UNIQUE(session_id, generation_id, source_table, source_column, source_ordinal)
) STRICT;

CREATE TABLE session_projection_aliases (
  session_id       TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE,
  generation_id    TEXT NOT NULL,
  native_key       TEXT NOT NULL,
  source_entry_ref TEXT NOT NULL,
  PRIMARY KEY (session_id, generation_id, native_key)
) STRICT;

CREATE TABLE session_projection_content (
  session_id       TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE,
  generation_id    TEXT NOT NULL,
  source_entry_ref TEXT NOT NULL,
  relative_blob    TEXT NOT NULL,
  byte_length      INTEGER NOT NULL CHECK(byte_length >= 0),
  integrity_digest TEXT NOT NULL,
  PRIMARY KEY (session_id, generation_id, source_entry_ref)
) STRICT;

CREATE TABLE session_projection_entries (
  session_id       TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE,
  generation_id    TEXT NOT NULL,
  partition_id     INTEGER NOT NULL CHECK(partition_id >= 0),
  entry_index      INTEGER NOT NULL CHECK(entry_index >= 0),
  source_entry_ref TEXT,
  entry_json       TEXT NOT NULL,
  PRIMARY KEY (session_id, generation_id, partition_id, entry_index)
) STRICT;

CREATE TABLE session_projection_generations (
  session_id             TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE,
  generation_id          TEXT NOT NULL,
  metadata_json          TEXT NOT NULL,
  title_refs_json        TEXT NOT NULL DEFAULT '[]',
  input_submission_count INTEGER CHECK(input_submission_count IS NULL OR (input_submission_count BETWEEN 0 AND 9007199254740991)),
  source_evidence_digest TEXT NOT NULL CHECK(length(source_evidence_digest) = 64),
  completeness           TEXT NOT NULL CHECK(completeness IN ('complete','incomplete_new')),
  index_format_version   INTEGER NOT NULL CHECK(index_format_version = 2),
  installed_at_ms        INTEGER NOT NULL CHECK(installed_at_ms >= 0),
  activated_at_ms        INTEGER CHECK(activated_at_ms IS NULL OR activated_at_ms >= 0),
  PRIMARY KEY (session_id, generation_id)
) STRICT;

CREATE TABLE "session_projection_sections" (
  session_id     TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE,
  generation_id  TEXT NOT NULL,
  partition_id   INTEGER NOT NULL CHECK(partition_id >= 0),
  earlier_state  TEXT,
  PRIMARY KEY (session_id, generation_id, partition_id)
) STRICT;

CREATE TABLE session_publication_metadata (
 session_id TEXT PRIMARY KEY REFERENCES sessions(session_id) ON DELETE CASCADE,
 capture_revision INTEGER NOT NULL CHECK (capture_revision > 0),
 schema_version INTEGER NOT NULL CHECK (schema_version > 0),
 metadata_json TEXT NOT NULL CHECK (json_valid(metadata_json)),
 metadata_hash TEXT NOT NULL CHECK (length(metadata_hash)=64 AND metadata_hash NOT GLOB '*[^0-9a-f]*'),
 content_hash TEXT NOT NULL CHECK (length(content_hash)=64 AND content_hash NOT GLOB '*[^0-9a-f]*'),
 captured_at INTEGER NOT NULL CHECK (captured_at > 0)
) STRICT;

CREATE TABLE session_publications (
  village_origin TEXT NOT NULL,
  owner_user_id TEXT NOT NULL,
  session_id TEXT NOT NULL,
  remote_transcript_id TEXT NOT NULL,
  transcript_url TEXT NOT NULL,
  project_hash TEXT NOT NULL,
  operation_fingerprint TEXT NOT NULL CHECK(length(operation_fingerprint) = 64),
  content_hash TEXT NOT NULL CHECK(length(content_hash) = 64),
  visibility TEXT NOT NULL CHECK(visibility IN ('private', 'group', 'public')),
  published_at INTEGER NOT NULL CHECK(published_at > 0),
  remote_updated_at INTEGER NOT NULL CHECK(remote_updated_at >= published_at),
  receipt_json TEXT NOT NULL CHECK(json_valid(receipt_json)),
  PRIMARY KEY (village_origin, owner_user_id, project_hash, session_id),
  UNIQUE (village_origin, owner_user_id, remote_transcript_id),
  FOREIGN KEY (session_id) REFERENCES sessions(session_id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "session_relationship_evidence" (
  session_id      TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE,
  generation_id   TEXT NOT NULL,
  ordinal         INTEGER NOT NULL CHECK(ordinal >= 0),
  kind            TEXT NOT NULL,
  target_state    TEXT NOT NULL CHECK(target_state IN
    ('target_known','target_known_retained','explicit_none','unknown',
     'conflicting_current_native_evidence')),
  target_local_id TEXT,
  evidence        TEXT,
  anchor_kind TEXT,
  anchor_source_entry_ref TEXT,
  anchor_source_revision_ref TEXT,
  PRIMARY KEY (session_id, generation_id, kind)
) STRICT;

CREATE VIRTUAL TABLE session_search_fts USING fts5(
  content_preview, tool_input, tool_output, session_id UNINDEXED, entry_index UNINDEXED,
  content='session_search_source', content_rowid='rid', tokenize='unicode61 remove_diacritics 2');

CREATE TABLE session_search_state (
  id            INTEGER PRIMARY KEY CHECK(id = 1),
  needs_rebuild INTEGER NOT NULL CHECK(needs_rebuild IN (0,1))
) STRICT;

CREATE TABLE session_section_native_metadata (
  session_id TEXT NOT NULL,
  generation_id TEXT NOT NULL,
  partition_id INTEGER NOT NULL,
  ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  native_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  source_entry_ref TEXT NOT NULL,
  source_type TEXT NOT NULL,
  source_message_role TEXT,
  attachment_turn_index INTEGER,
  attachment_tool_call_id TEXT,
  custom_type TEXT,
  data TEXT,
  PRIMARY KEY (session_id, generation_id, partition_id, ordinal),
  FOREIGN KEY (session_id, generation_id, partition_id)
    REFERENCES session_projection_sections(session_id, generation_id, partition_id) ON DELETE CASCADE
) STRICT;

CREATE TABLE session_source_unavailability (
 session_id TEXT PRIMARY KEY REFERENCES sessions(session_id) ON DELETE CASCADE,
 reason TEXT NOT NULL CHECK (reason IN ('original-source-unavailable-no-usable-saved-copy'))
) STRICT;

CREATE TABLE sessions (
    session_id TEXT PRIMARY KEY,
    parent_id TEXT REFERENCES sessions(session_id),
    model_harness TEXT NOT NULL CHECK (model_harness IN ('claude-code','opencode','codex','gemini-cli','cursor','antigravity','strike','pi')),
    model_id TEXT NOT NULL,
    opaque_host_id TEXT NOT NULL REFERENCES host_slugs(opaque_id),
    project_hash TEXT NOT NULL REFERENCES projects(project_hash),
    start_ms INTEGER NOT NULL,
    end_ms INTEGER NOT NULL,
    ingested_ms INTEGER NOT NULL,
    source_path TEXT NOT NULL,
    source_format TEXT NOT NULL CHECK (source_format IN ('jsonl','json')),
    schema_version INTEGER NOT NULL DEFAULT 1,
    git_branch TEXT,
    git_worktree TEXT,
    git_tracking TEXT,
    tool_version TEXT,
    pushed_at INTEGER,
    tags TEXT,
    index_version INTEGER NOT NULL DEFAULT 0,
    indexed_at INTEGER,
    license_id TEXT CHECK (license_id IN ('CC0-1.0', 'CC-BY-4.0', 'CC-BY-SA-4.0')),
    session_origin TEXT NOT NULL DEFAULT 'unknown' CHECK (session_origin IN ('user','agent','unknown')),
    origin_version INTEGER NOT NULL DEFAULT 0,
    session_entries_hash TEXT CHECK (session_entries_hash IS NULL OR (length(session_entries_hash) = 64 AND session_entries_hash NOT GLOB '*[^0-9a-f]*')),
    source_fingerprint BLOB,
    session_cwd TEXT,
    cwd_provenance_kind TEXT NOT NULL DEFAULT 'not_recovered' CHECK(cwd_provenance_kind IN ('source_exact','source_workspace','source_worktree','source_absent','not_recovered')),
    publication_capture_revision INTEGER NOT NULL DEFAULT 0 CHECK(publication_capture_revision >= 0),
    indexed_publication_capture_revision INTEGER NOT NULL DEFAULT 0 CHECK(indexed_publication_capture_revision >= 0)
, index_format_version INTEGER CHECK (index_format_version > 0), adapter_version INTEGER CHECK (adapter_version > 0), artifact_hash TEXT CHECK (artifact_hash IS NULL OR (length(artifact_hash) = 64 AND artifact_hash NOT GLOB '*[^0-9a-f]*')), metric_seed_json TEXT CHECK (metric_seed_json IS NULL OR json_valid(metric_seed_json)), indexed_input_hash TEXT CHECK (
    indexed_input_hash IS NULL OR (
        length(indexed_input_hash) = 64 AND indexed_input_hash NOT GLOB '*[^0-9a-f]*'
    )
), active_generation_id TEXT, root_session_id TEXT, session_purpose TEXT, input_submission_count INTEGER CHECK(input_submission_count IS NULL OR (input_submission_count BETWEEN 0 AND 9007199254740991)), content_sweep_pending INTEGER NOT NULL DEFAULT 0 CHECK(content_sweep_pending IN (0,1))) STRICT;

CREATE TABLE target_kinds (
